// Probe for looking at dispatch-pilot's screens: answers its reads of `board`,
// `decisionLog` and `skillProfiles` with fixed scenes (times relative to now),
// so the real band, footer and rationale pane draw a busy turn without any
// model or decision request. `/dpscene <name>` picks one (README.md lists them);
// DP_SCENE=<name> at launch picks the first.
//
// The scenes follow dispatch-pilot's PluginState contract (dispatch-pilot/types/index.d.ts)
// as of 0.3.1; a field the contract gains is absent here until a scene needs it.

import type { Register } from 'claude-code'

type Node = Record<string, unknown>
type Entry = Record<string, unknown>
type Scene = { board: { turn: number; starts: { turn: number; at: number }[]; changes?: unknown[]; notes?: unknown[]; nodes: Node[] }; log: Entry[]; profiles?: Record<string, unknown> }

const levels = ['low', 'medium', 'high', 'xhigh', 'max'] as const
const probs = (...p: number[]) => Object.fromEntries(levels.map((level, i) => [level, p[i] ?? 0]))

/** The steps pickEffort records: the most likely level, the max gate, the round-up. */
const pick = (top: string, p: number, gate: number, up: { above: string | null; p: number; applied: boolean; level: string }) => [
  { rule: 'top', applied: true, level: top, p, tie: false },
  { rule: 'max-gate', applied: false, level: top, p: gate, thetaMax: 0.5 },
  { rule: 'round-up', applied: up.applied, level: up.level, above: up.above, p: up.p, threshold: 0.3, blockedByMax: false, thetaMax: 0.5 },
]

function agent(turn: number, id: string, name: string, model: string, effort: string | undefined, state: string, t0: number, extra: Node = {}): Node {
  return { turn, id, kind: 'agent', name, type: 'general-purpose', model, ...(effort === undefined ? {} : { effort }), state, t0, routed: true, ...extra }
}

const TIMEOUT = { why: 'jev：1500 毫秒内没有回答', failure: { backend: 'jev', kind: 'timeout', detail: 'no answer in 1500 ms' } }

function scenes(now: number): Record<string, Scene> {
