      { n: 31, turn: 7, at: 75, feature: 'midturn-effort', agent: 'main', tone: 'info', outcome: 'effort xhigh（不变）', subject: '第 8 步（每 3 步）', reason: '防抖：2 步前刚升档（holdSteps 5）', conf: 0.9, mid: { current: 'xhigh', picked: 'medium', result: 'xhigh', held: '防抖：2 步前刚升档（holdSteps 5）', remaining: 3 }, trace: [{ rule: 'suggest', applied: true, picked: 'medium', current: 'xhigh', direction: 'down' }, { rule: 'hold', applied: true, sinceRaise: 2, holdSteps: 5, remaining: 3 }] },
      { n: 32, turn: 7, at: 90, feature: 'midturn-effort', agent: 'main', tone: 'info', outcome: 'effort xhigh（不变）', subject: '第 11 步（每 3 步）', reason: 'high 把握不够（降档要 thetaDown 0.55）', conf: 0.42, mid: { current: 'xhigh', picked: 'high', result: 'xhigh', threshold: 0.55 }, trace: [{ rule: 'suggest', applied: true, picked: 'high', current: 'xhigh', direction: 'down' }, { rule: 'hold', applied: false, sinceRaise: 5, holdSteps: 5, remaining: 0 }, { rule: 'theta-down', applied: false, confidence: 0.42, threshold: 0.55 }] },
