/** The scene shown: the person's last `/dpscene`. A hot reload starts over at DP_SCENE (or `agents`). */
let scene = 'agents'

export const register: Register = (on) => {
  on('session.start', { cwd: /(?:)/ }, async ($, e, next) => {
    const result = await next(e)
    scene = (await $.env.get('DP_SCENE').catch(() => undefined)) ?? scene
    await $.command.register({ name: 'dpscene', description: 'probe: pick the fake board scene', argumentHint: 'agents|writing|stopped|workflow|notrouted|idle|many', immediate: true }).catch(() => undefined)
    return result
  })
  on('command.run', { command: 'dpscene' }, async ($, e) => {
    const want = e.args.trim()
    if (want !== '') scene = want
    $.ui.invalidate('ui.render')
    return { text: `scene ${scene}` }
  })
  const of = async (now: Promise<number>) => {
    const all = scenes(await now)
    return all[scene] ?? all.agents
  }
  on('state.get', { plugin: 'dispatch-pilot', key: 'board' }, async ($) => ({ value: { value: (await of($.clock.now()))?.board as never, version: 1 } }))
  on('state.get', { plugin: 'dispatch-pilot', key: 'decisionLog' }, async ($) => ({ value: { value: (await of($.clock.now()))?.log as never, version: 1 } }))
  on('state.get', { plugin: 'dispatch-pilot', key: 'skillProfiles' }, async ($) => ({ value: { value: (await of($.clock.now()))?.profiles as never, version: 1 } }))
}

